  const logoSlugs: Record<string, string> = { LinkedIn: "linkedin", Instagram: "instagram", Reddit: "reddit", X: "x", Facebook: "facebook", YouTube: "youtube", GitHub: "github", Naukri: "naukri", "WhatsApp Business": "whatsapp" };
  const symbols: Record<string, string> = { LinkedIn: "in", Instagram: "◎", Reddit: "R", X: "X", Facebook: "f", YouTube: "▶", GitHub: "⌘", Naukri: "N", "WhatsApp Business": "WA", Other: "↗" };
  const [platform, setPlatform] = useState("");
  const [url, setUrl] = useState("");
  const handlePlatformChange = (nextPlatform: string) => { setPlatform(nextPlatform); setUrl(prefixes[nextPlatform] ?? ""); };
