function SimpleField({ label, placeholder, type = "text", required = false }: { label: string; placeholder: string; type?: string; required?: boolean }) {
  const [value, setValue] = useState("");
  return <label className="block"><span className="mb-1.5 block text-xs font-semibold text-foreground dark:text-slate-200">{label}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span><input type={type} required={required} value={value} onChange={(event) => setValue(event.target.value)} placeholder={placeholder} className={cn("h-10 w-full rounded-xl border border-border bg-background px-3 text-sm outline-none transition focus:border-amber-500/50 focus:ring-2 focus:ring-amber-500/20 dark:border-white/10 dark:bg-slate-950/40 dark:text-white", type === "date" && "cursor-pointer")} /></label>;
}

function Field({ label, placeholder, type = "text", required = false }: { label: string; placeholder: string; type?: string; required?: boolean }) {
  const isOtherSkills = label === "Other skills / tools";
  const isMobileNumber = label === "Mobile number (with country code)";
  const identityContact = useContext(IdentityContactContext);
  const selectedCountry = COUNTRY_OPTIONS.find((country) => country.name === identityContact?.country);
  const [mobileValue, setMobileValue] = useState("");
  const [fieldValue, setFieldValue] = useState("");
  useEffect(() => { if (isMobileNumber && selectedCountry) setMobileValue((current) => current.trim() ? current.replace(/^\+\d+\s*/, selectedCountry.dialCode + " ") : selectedCountry.dialCode + " "); }, [isMobileNumber, selectedCountry]);
  const displayLabel = label === "Preferred display name" ? "Full name display" : label === "Current / most recent employer" ? "Previous/current company" : label === "Current / most recent job title" ? "Job title" : label === "Typical / average deal size" ? "Average deal size" : label === "Annual / quarterly sales target" ? "Quota / annual sales target" : label === "Target achievement" ? "Quota achievement" : label === "Minimum commission rate you'd accept" ? "Expected commission rate" : label;
  if (label === "Create password" || label === "Confirm password" || label === "Personal Website / Portfolio") return null;
  if (label === "LinkedIn Profile URL") return <ForcedDownSocialLinksField required={required} />;
  if (label === "City") return <><SimpleField label={displayLabel} placeholder={placeholder} required={required} /><SimpleField label="State / Province" placeholder="e.g. Maharashtra / California" required /></>;
  return <label className="block"><span className="mb-1.5 block text-xs font-semibold text-foreground dark:text-slate-200">{displayLabel}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span><div className="relative"><input type={type} required={required} value={isMobileNumber ? mobileValue : fieldValue} onChange={(event) => isMobileNumber ? setMobileValue(event.target.value) : setFieldValue(event.target.value)} placeholder={isMobileNumber && selectedCountry ? `${selectedCountry.dialCode} mobile number` : placeholder} onClick={(event) => { if (type === "date" && typeof event.currentTarget.showPicker === "function") { try { event.currentTarget.showPicker(); } catch { /* Native picker may already be open. */ } } }} className={cn("h-10 w-full rounded-xl border border-border bg-background px-3 text-sm outline-none transition focus:border-amber-500/50 focus:ring-2 focus:ring-amber-500/20 dark:border-white/10 dark:bg-slate-950/40 dark:text-white", type === "date" && "cursor-pointer", isOtherSkills && "pr-28" )} />{isOtherSkills && <button type="button" onClick={(event) => { event.preventDefault(); const input = event.currentTarget.previousElementSibling; if (input instanceof HTMLInputElement) input.focus(); }} className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded-lg bg-amber-500/10 px-2.5 py-1.5 text-[11px] font-bold text-amber-700 hover:bg-amber-500/20 dark:text-amber-300">+ Add skill</button>}</div></label>;
}

function SelectField({ label, options, required = false }: { label: string; options: string[]; required?: boolean }) {
  const identityContact = useContext(IdentityContactContext);
  if (label === "Title") return null;
  const isCountry = label === "Country of residence";
  const isTimeZone = label === "Time zone";
  const displayLabel = label === "Preferred payout method" ? "Preferred payment method" : label;
  if (isCountry) return <CountrySearchField displayLabel={displayLabel} required={required} />;
  const selectedCountryInfo = COUNTRY_OPTIONS.find((country) => country.name === identityContact?.country);
  const selectOptions = isCountry ? ["Select country", ...COUNTRY_OPTIONS.map((country) => country.name)] : isTimeZone ? TIME_ZONE_OPTIONS : options;
  const selectedValue = isCountry ? identityContact?.country ?? "" : isTimeZone ? identityContact?.timeZone ?? "" : undefined;
  return <><label className="block"><span className="mb-1.5 block text-xs font-semibold text-foreground dark:text-slate-200">{displayLabel}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span><div className={cn("relative", isCountry && "country-select-with-flag")}>{isCountry && selectedCountryInfo && <span className="pointer-events-none absolute left-3 top-1/2 z-10 -translate-y-1/2" aria-hidden="true"><CountryFlag name={selectedCountryInfo.name} /></span>}<select required={required} value={selectedValue} onChange={isCountry ? (event) => { const country = COUNTRY_OPTIONS.find((item) => event.target.value === item.name); if (country) { identityContact?.setCountry(country.name); identityContact?.setTimeZone(country.timeZone); } } : isTimeZone ? (event) => identityContact?.setTimeZone(event.target.value) : undefined} className={cn("h-10 w-full rounded-xl border border-border bg-background px-3 text-sm text-foreground outline-none transition focus:border-amber-500/50 focus:ring-2 focus:ring-amber-500/20 dark:border-white/10 dark:bg-slate-950/40 dark:text-white", isCountry && "pl-10")}>{selectOptions.map((option, index) => <option key={option} value={index === 0 ? "" : isCountry ? COUNTRY_OPTIONS[index - 1].name : option}>{option}</option>)}</select></div></label>{label === "Preferred way of working" && <><SelectField label="Availability" options={["Select availability", "Available now", "Available next week", "Available next month", "Limited capacity"]} required /><SelectField label="Full-time / part-time" options={["Select commitment", "Full-time", "Part-time"]} required /><SelectField label="Remote / on-site" options={["Select work location", "Remote", "On-site", "Hybrid"]} required /></>}</>;
}

function CountrySearchField({ displayLabel, required }: { displayLabel: string; required: boolean }) {
  const identityContact = useContext(IdentityContactContext);
  const selectedCountryInfo = COUNTRY_OPTIONS.find((country) => country.name === identityContact?.country);
  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const country = COUNTRY_OPTIONS.find((item) => item.name === event.target.value);
    identityContact?.setCountry(event.target.value);
    if (country) identityContact?.setTimeZone(country.timeZone);
  };
  return <label className="block">
    <span className="mb-1.5 block text-xs font-semibold text-foreground dark:text-slate-200">{displayLabel}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span>
    <div className="relative">
      {selectedCountryInfo && <span className="pointer-events-none absolute left-3 top-1/2 z-10 -translate-y-1/2" aria-hidden="true"><CountryFlag name={selectedCountryInfo.name} /></span>}
      <input list="account-country-options" value={identityContact?.country ?? ""} onChange={handleChange} placeholder="Type or select country" required={required} className={cn("h-10 w-full rounded-xl border border-border bg-background px-3 text-sm text-foreground outline-none transition focus:border-amber-500/50 focus:ring-2 focus:ring-amber-500/20 dark:border-white/10 dark:bg-slate-950/40 dark:text-white", selectedCountryInfo && "pl-10")} />
      <datalist id="account-country-options">{COUNTRY_OPTIONS.map((country) => <option key={country.name} value={country.name} />)}</datalist>
    </div>
  </label>;
}

function TextAreaField({ label, placeholder, required = false }: { label: string; placeholder: string; required?: boolean }) {
  const displayLabel = label === "Key Sales Achievements" ? "Quota and achievements" : label;
  return <label className="block"><span className="mb-1.5 block text-xs font-semibold text-foreground dark:text-slate-200">{displayLabel}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span><textarea required={required} rows={4} placeholder={placeholder} className="w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm outline-none transition focus:border-amber-500/50 focus:ring-2 focus:ring-amber-500/20 dark:border-white/10 dark:bg-slate-950/40 dark:text-white" /></label>;
}

function ChoiceGroup({ label, options, required = false }: { label: string; options: string[]; required?: boolean }) {
  return <fieldset><legend className="mb-2 text-xs font-semibold text-foreground dark:text-slate-200">{label}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</legend><div className="grid gap-2 sm:grid-cols-3">{options.map((option) => <label key={option} className="flex cursor-pointer items-center gap-2 rounded-xl border border-border/70 bg-background/60 p-3 text-xs text-muted-foreground transition hover:border-amber-500/40 dark:border-white/5 dark:bg-slate-950/40 dark:text-slate-300"><input type="radio" name={label} value={option} required={required} className="accent-amber-500" />{option}</label>)}</div></fieldset>;
}

function ConsentRow({ text, required = false }: { text: string; required?: boolean }) {
  return <label className="flex items-start gap-3 rounded-xl border border-border/70 bg-background/60 p-4 text-sm dark:border-white/5 dark:bg-slate-950/40"><input type="checkbox" required={required} className="mt-0.5 h-4 w-4 accent-amber-500" /><span className="text-muted-foreground dark:text-slate-300">{text}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span></label>;
}

function UploadRow({ label, hint, required = false }: { label: string; hint: string; required?: boolean }) {
  return <label className="block rounded-xl border border-dashed border-border bg-background/50 p-4 transition hover:border-amber-500/50 dark:border-white/10 dark:bg-slate-950/30"><span className="block text-xs font-semibold text-foreground dark:text-slate-200">{label}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span><span className="mt-1 block text-[11px] text-muted-foreground">{hint}</span><input type="file" required={required} className="mt-3 block w-full text-xs text-muted-foreground file:mr-3 file:rounded-lg file:border-0 file:bg-amber-500/15 file:px-3 file:py-1.5 file:text-xs file:font-semibold file:text-amber-700 dark:file:text-amber-300" /></label>;
}

function Notice({ text }: { text: string }) {
  return <div className="rounded-xl border border-cyan-500/20 bg-cyan-500/5 px-4 py-3 text-xs text-muted-foreground dark:text-slate-300">{text}</div>;
}
